# -*- coding: utf-8 -*-
"""sci_ecsa_qc.py — ECSA 批量 QC（Phase 3c 落地版）

把复盘建议 #1–#5 固化为五道门：
  G1 每个系列扫速数 ≥3（否则拒绝出数）
  G2 所有系列共用同一 e0（不同则 BLOCK，除非配置显式允许）
  G3 Cs 必须带 值/来源/适用体系（缺一即 BLOCK）
  G4 R² 分级：≥0.99 点值；0.9–0.99 半定量（WARN）；<0.9 BLOCK
  G5 回原始 CV 对账：拟合预测 vs 原始 Δj/2 偏差 >10% 即 BLOCK

用法：
  python tools/sci_ecsa_qc.py --config ecsa_qc.yaml
  python tools/sci_ecsa_qc.py --selftest

配置（YAML/JSON）：
  cs: {value_uF_cm2: 60, source: "…", system: "…"}
  area_cm2: 1.0
  tol_V: 0.005
  allow_different_e0: false
  series:
    - {name: ECSA.2, e0: -0.15, files: [a.txt, b.txt, c.txt]}
"""

import argparse
import datetime
import json
import os
import sys

TOOLS_DIR = os.path.dirname(os.path.abspath(__file__))
sys.path.insert(0, TOOLS_DIR)

import kb_lib as K  # noqa: E402
import sci_data_analysis as A  # noqa: E402
K.console_encoding()

CONFIG_REL = "projects/sci-assistant/config/sci_assistant_config.yaml"


def load_config(path):
    import yaml
    with open(path, "r", encoding="utf-8") as f:
        return yaml.safe_load(f) or {}


def load_series(cfg):
    out = []
    for s in cfg.get("series") or []:
        files = s.get("files") or []
        out.append({"name": s.get("name") or (os.path.basename(files[0]) if files else "S"),
                    "e0": float(s["e0"]), "files": files,
                    "tol": s.get("tol")})
    return out


def scan_points(series, tol, area):
    pts, raw = [], {}
    for f in series["files"]:
        ds = A.read_dataset(f)
        nu = float(ds["params"].get("Scan Rate (V/s)"))
        cur = A.currents_at(ds["rows"], series["e0"], tol)
        if not cur:
            raise SystemExit(f"[!] {f} 在 e0={series['e0']} ±{tol} 无采样点")
        dj = (max(cur) - min(cur)) * 1000.0 / float(area)
        pts.append((nu, dj / 2.0))
        raw[f] = {"scan_rate": nu, "delta_j_half": dj / 2.0}
    return pts, raw


def qc_series(series, cfg, all_e0):
    area = float(cfg.get("area_cm2") or 1.0)
    tol = float(series.get("tol") or cfg.get("tol_V") or 0.005)
    cs = cfg.get("cs") or {}
    gates = []

    pts, raw = scan_points(series, tol, area)
    # G1
    rates = sorted(p[0] for p in pts)
    if len(rates) < 3:
        gates.append(("G1", "BLOCK", f"扫速数 {len(rates)} < 3"))
    else:
        gates.append(("G1", "PASS", f"{len(rates)} 个扫速：{rates}"))

    # G2
    if cfg.get("allow_different_e0"):
        gates.append(("G2", "WARN", "配置允许不同 e0；跨系列不可直接横向比较"))
    elif len(set(round(e, 6) for e in all_e0)) > 1:
        gates.append(("G2", "BLOCK", f"系列 e0 不一致：{sorted(set(all_e0))}"))
    else:
        gates.append(("G2", "PASS", f"e0 = {series['e0']}"))

    # G3
    missing = [k for k in ("value_uF_cm2", "source", "system") if not cs.get(k)]
    if missing:
        gates.append(("G3", "BLOCK", f"Cs 元数据缺：{missing}"))
    else:
        gates.append(("G3", "PASS",
                      f"Cs={cs['value_uF_cm2']} µF/cm²（{cs['source']}；{cs['system']}）"))

    # 拟合（≥3 才能走到这里；不足时用 2 点仅算示例并标 BLOCK）
    if len(pts) < 2:
        return {"series": series["name"], "e0": series["e0"], "gates": gates,
                "cdl": None, "r2": None, "ecsa": None, "raw": raw, "points": pts}
    res = A.fit_ecsa_points(pts, float(cs.get("value_uF_cm2") or 60.0), area)

    # G4
    r2 = res["r2"]
    if r2 >= 0.99:
        gates.append(("G4", "PASS", f"R²={r2:.4f} → 报点值"))
    elif r2 >= 0.9:
        gates.append(("G4", "WARN", f"R²={r2:.4f} → 半定量，不报点值"))
    else:
        gates.append(("G4", "BLOCK", f"R²={r2:.4f} < 0.9 → 不成立，待重扫"))

    # G5 回原始 CV 对账
    worst = 0.0
    for nu, dj2 in pts:
        pred = res["slope_mF_cm2"] * nu + res["intercept"]
        dev = abs(pred - dj2) / abs(dj2) if dj2 else 0.0
        worst = max(worst, dev)
    if worst > 0.10:
        gates.append(("G5", "BLOCK", f"回原始 CV 对账最大偏差 {worst*100:.1f}% > 10%"))
    else:
        gates.append(("G5", "PASS", f"对账最大偏差 {worst*100:.1f}%"))

    return {"series": series["name"], "e0": series["e0"], "gates": gates,
            "cdl": res["cdl_mF_cm2"], "r2": r2, "ecsa": res["ecsa_cm2"],
            "rf": res["rf"], "points": res["points"], "raw": raw}


def verdict(results):
    levels = [g[1] for r in results for g in r["gates"]]
    if "BLOCK" in levels:
        return "BLOCK"
    if "WARN" in levels:
        return "WARN"
    return "PASS"


def render(results, cfg, v):
    L = ["# ECSA 批量 QC", ""]
    L.append(f"> 生成于 {datetime.date.today().isoformat()} ｜ 判定：**{v}** ｜ "
             f"Cs={((cfg.get('cs') or {}).get('value_uF_cm2'))} µF/cm² ｜ "
             f"面积 {cfg.get('area_cm2')} cm²")
    L.append("")
    L.append("## 系列")
    L.append("")
    L.append("| 系列 | e0 (V) | Cdl (mF cm⁻²) | R² | ECSA (cm²) | 判定 |")
    L.append("|---|---|---|---|---|---|")
    for r in results:
        rv = "BLOCK" if any(g[1] == "BLOCK" for g in r["gates"]) else (
            "WARN" if any(g[1] == "WARN" for g in r["gates"]) else "PASS")
        L.append(f"| {r['series']} | {r['e0']} | {r['cdl'] if r['cdl'] is not None else '—'} | "
                 f"{r['r2'] if r['r2'] is not None else '—'} | "
                 f"{r['ecsa'] if r['ecsa'] is not None else '—'} | {rv} |")
    L.append("")
    L.append("## 逐项门禁")
    L.append("")
    for r in results:
        L.append(f"### {r['series']}")
        L.append("")
        for g, st, msg in r["gates"]:
            L.append(f"- `{g}` **{st}**：{msg}")
        L.append("")
    L.append("## 边界")
    L.append("")
    L.append("- G1–G5 是复盘建议的机械落地；BLOCK 的系列不得进入结论。")
    L.append("- G5 只对比拟合预测与原始 e0 处 Δj/2，不替代人工目检。")
    L.append("")
    return "\n".join(L)


# ---------------------------------------------------------------- 自检

def _make_scans(k=5.0, c=0.0, noise=0.0):
    scans = []
    for nu in (0.005, 0.007, 0.01):
        mid = k * nu + c
        scans.append((nu, [-(mid - noise) / 1000.0, (mid + noise) / 1000.0]))
    return scans


def _selftest():
    fails = []

    def chk(label, cond, detail=""):
        print(("  ok   " if cond else "  FAIL ") + label +
              (f"   [{detail}]" if detail and not cond else ""))
        if not cond:
            fails.append(label)

    base = {"cs": {"value_uF_cm2": 60, "source": "文献", "system": "NiFe in KOH"},
            "area_cm2": 1.0, "tol_V": 0.005, "allow_different_e0": True}

    pts = _make_scans(5.0)
    res = A.ecsa_from_scans(pts, 60.0, 1.0, min_rates=3)
    chk("线性数据：Cdl=5", abs(res["cdl_mF_cm2"] - 5) < 1e-9)
    chk("线性数据：ECSA=83.3", abs(res["ecsa_cm2"] - 5 / 0.06) < 1e-9)

    def run(series, cfg):
        all_e0 = [series["e0"]]
        return qc_series(series, cfg, all_e0)

    tmp = K.make_temp_dir(prefix="sci_ecsa_qc_")
    try:
        files = []
        for i, (nu, cur) in enumerate(_make_scans(5.0)):
            p = os.path.join(tmp, f"s{i}.txt")
            with open(p, "w", encoding="utf-8", newline="\n") as f:
                f.write("Jan. 1, 2026 00:00:00\nCyclic Voltammetry\n"
                        f"Instrument Model: CHI760E\nScan Rate (V/s) = {nu}\n\n"
                        "Potential/V, Current/A\n")
                f.write(f"0.000, {cur[0]}\n0.001, {cur[1]}\n")
            files.append(p)
        s = {"name": "S", "e0": 0.0, "files": files}
        r = run(s, base)
        chk("G1/G3/G4/G5 正常数据 PASS",
            all(g[1] == "PASS" for g in r["gates"] if g[0] in ("G1", "G3", "G4", "G5")))
        chk("G2 允许不同 e0 时 WARN", any(g[0] == "G2" and g[1] == "WARN"
                                          for g in r["gates"]))

        bad = dict(base, cs={"value_uF_cm2": 60})
        r2 = run(s, bad)
        chk("G3 缺 Cs 元数据 BLOCK",
            any(g[0] == "G3" and g[1] == "BLOCK" for g in r2["gates"]))

        s2 = {"name": "S2", "e0": 0.0, "files": files[:2]}
        r3 = run(s2, base)
        chk("G1 扫速<3 BLOCK",
            any(g[0] == "G1" and g[1] == "BLOCK" for g in r3["gates"]))

        # G4：三点非线性 → R² 低
        nl = []
        for i, (nu, cur) in enumerate(_make_scans(5.0)):
            p = os.path.join(tmp, f"n{i}.txt")
            with open(p, "w", encoding="utf-8", newline="\n") as f:
                f.write("Jan. 1, 2026 00:00:00\nCyclic Voltammetry\n"
                        f"Instrument Model: CHI760E\nScan Rate (V/s) = {nu}\n\n"
                        "Potential/V, Current/A\n")
                f.write(f"0.000, {cur[0]}\n0.001, {cur[1]}\n")
            nl.append(p)
        # 把第三个扫速的电流改大，制造弯曲
        p = nl[2]
        with open(p, "a", encoding="utf-8", newline="\n") as f:
            f.write("0.002, 0.02\n")
        r4 = run({"name": "S4", "e0": 0.0, "files": nl}, base)
        chk("G4 低 R² BLOCK", any(g[0] == "G4" and g[1] == "BLOCK" for g in r4["gates"]))
    finally:
        K.remove_temp_dir(tmp)

    print(f"SELFTEST {'PASSED' if not fails else 'FAILED'}: {len(fails)} failure(s)")
    return 0 if not fails else 1


# ---------------------------------------------------------------- CLI

def main(argv=None):
    ap = argparse.ArgumentParser(description="ECSA 批量 QC（五道门）")
    ap.add_argument("--config", help="QC 配置 YAML/JSON")
    ap.add_argument("--out", default=None, help="输出目录（默认 data_analysis/<日期>-ecsa-qc）")
    ap.add_argument("--selftest", action="store_true")
    args = ap.parse_args(argv)

    if args.selftest:
        return _selftest()
    if not args.config:
        ap.print_help()
        return 1

    cfg = load_config(args.config)
    series = load_series(cfg)
    all_e0 = [s["e0"] for s in series]
    results = [qc_series(s, cfg, all_e0) for s in series]
    v = verdict(results)
    md = render(results, cfg, v)

    p = args.config
    if os.path.isfile(os.path.join(K.VAULT, CONFIG_REL)):
        import yaml
        with open(os.path.join(K.VAULT, CONFIG_REL), encoding="utf-8") as f:
            base = yaml.safe_load(f) or {}
    else:
        base = {}
    out_dir = args.out or os.path.join(
        K.VAULT, (base.get("sci") or {}).get("data_analysis_dir",
                                             "projects/sci-assistant/data_analysis"),
        f"{datetime.date.today().isoformat()}-ecsa-qc")
    os.makedirs(out_dir, exist_ok=True)
    p_md = os.path.join(out_dir, "ecsa_qc.md")
    with open(p_md, "w", encoding="utf-8", newline="\n") as f:
        f.write(md + "\n")
    p_js = os.path.join(out_dir, "ecsa_qc.json")
    with open(p_js, "w", encoding="utf-8", newline="\n") as f:
        json.dump({"verdict": v, "config": cfg, "results": results},
                  f, ensure_ascii=False, indent=2)
        f.write("\n")
    print(f"[{v}] ECSA QC：{len(series)} 个系列")
    for r in results:
        rv = "BLOCK" if any(g[1] == "BLOCK" for g in r["gates"]) else (
            "WARN" if any(g[1] == "WARN" for g in r["gates"]) else "PASS")
        print(f"  - {r['series']}：{rv}  Cdl={r['cdl']}  R²={r['r2']}  ECSA={r['ecsa']}")
    print(f"  输出：{os.path.relpath(p_md, K.VAULT)}")
    return 0 if v != "BLOCK" else 2


if __name__ == "__main__":
    sys.exit(main())
